from ortools.sat.python import cp_model
import json

def solve_parcel_packing():
    parcels = [
        ("A", 45.2), ("B", 32.1), ("C", 28.7), ("D", 39.8), ("E", 21.7),
        ("F", 48.3), ("G", 35.6), ("H", 27.4), ("I", 41.9), ("J", 33.3),
        ("K", 29.1), ("L", 46.7), ("M", 37.8), ("N", 24.9), ("O", 31.2),
        ("P", 42.6), ("Q", 26.5), ("R", 38.4), ("S", 49.0), ("T", 22.8),
        ("U", 30.1), ("V", 47.5), ("W", 34.2), ("X", 28.9), ("Y", 36.7),
        ("Z", 43.1), ("AA", 25.5), ("AB", 39.4), ("AC", 40.2), ("AD", 23.6),
        ("AE", 31.8), ("AF", 44.9), ("AG", 35.3), ("AH", 27.7), ("AI", 48.8),
        ("AJ", 36.2), ("AK", 29.5), ("AL", 41.1), ("AM", 26.3), ("AN", 37.6),
        ("AO", 45.9), ("AP", 24.4), ("AQ", 32.5), ("AR", 46.1), ("AS", 28.2),
        ("AT", 33.8), ("AU", 39.7), ("AV", 27.1), ("AW", 42.3), ("AX", 30.0)
    ]

    n_parcels = len(parcels)
    parcel_names = [p[0] for p in parcels]
    parcel_volumes = [p[1] for p in parcels]

    SCALE_FACTOR = 10
    scaled_volumes = [int(v * SCALE_FACTOR) for v in parcel_volumes]

    C = 100.0
    scaled_C = int(C * SCALE_FACTOR)
    M = n_parcels

    model = cp_model.CpModel()

    x = {}
    for i in range(n_parcels):
        for k in range(M):
            x[(i, k)] = model.NewBoolVar(f"x_{i}_{k}")

    y = [model.NewBoolVar(f"y_{k}") for k in range(M)]

    for i in range(n_parcels):
        model.Add(sum(x[(i, k)] for k in range(M)) == 1)

    for k in range(M):
        volume_expr = sum(scaled_volumes[i] * x[(i, k)] for i in range(n_parcels))
        model.Add(volume_expr <= scaled_C)

    for k in range(M):
        for i in range(n_parcels):
            model.Add(x[(i, k)] <= y[k])

    for k in range(M - 1):
        model.Add(y[k] >= y[k + 1])

    model.Minimize(sum(y[k] for k in range(M)))

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 60.0
    solver.parameters.num_search_workers = 8
    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        used_trucks = []
        for k in range(M):
            if solver.Value(y[k]) == 1:
                used_trucks.append(k)

        truck_loads = []
        for k in used_trucks:
            parcel_indices = []
            for i in range(n_parcels):
                if solver.Value(x[(i, k)]) == 1:
                    parcel_indices.append(i + 1)
            truck_loads.append(parcel_indices)

        result = {
            "num_trucks": len(used_trucks),
            "truck_loads": truck_loads
        }
        print(json.dumps(result))

    else:
        result = {
            "num_trucks": 0,
            "truck_loads": []
        }
        print(json.dumps(result))

if __name__ == "__main__":
    solve_parcel_packing()
